import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"植物大战僵尸移植 · 模组开发","text":"从零写一个模组，到用 Mixin 与内容 API 改写游戏","tagline":"PvZ-Portable（Java 移植版）的模组作者文档，中文与英文各一份","actions":[{"theme":"brand","text":"开始","link":"/guide/index"},{"theme":"alt","text":"API 速查","link":"/guide/reference"}]},"features":[{"title":"1. 开始","details":"前置条件、怎么把游戏跑起来、mods/ 目录在哪、第一个能跑起来的空模组"},{"title":"2. 项目结构","details":"以 pvz-content-mod 为例的工程骨架、两个构建脚本、fabric.mod.json 的每个字段、run/ 的语义"},{"title":"3. 实验 Mixin","details":"选目标类、写 mixin 配置、@Inject/@Redirect/@ModifyConstant/@Accessor 的完整可复制例子与 require 语义"},{"title":"4. 用 fabric-api 做内容","details":"注册植物与僵尸、覆盖已有数值、图片与 reanimation、资源覆盖、事件与生命周期"},{"title":"5. 实例精读","details":"按文件走一遍 pvz-content-mod：注册、艺术管线、种子包绘制、解锁门控"},{"title":"6. 构建、测试与发布","details":"build/test/runClient、端到端测试的思路、publishToMavenLocal、把 jar 交给玩家"},{"title":"7. API 速查","details":"各模块的公开 API 一览，以及去哪读真实实现"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="这份文档是什么" tabindex="-1">这份文档是什么 <a class="header-anchor" href="#这份文档是什么" aria-label="Permalink to “这份文档是什么”">​</a></h2><p>这个站点只讲一件事：<strong>给 PvZ-Portable 写模组</strong>。PvZ-Portable 是《植物大战僵尸》GOTY 的 Java 桌面移植版（JDK 25 + Gradle + LWJGL/SDL3），它<strong>跑在真正的 Fabric Loader 上</strong>，所以模组就是 普通的 Fabric 模组：一份 <code>fabric.mod.json</code>、一个 <code>ModInitializer</code> 入口点、一个 jar。</p><p>内容按&quot;从零到能改游戏&quot;的顺序组织：</p><table tabindex="0"><thead><tr><th>章节</th><th>读它是为了</th></tr></thead><tbody><tr><td><a href="./guide/">1. 开始</a></td><td>把环境和游戏准备好，让第一个空模组跑起来</td></tr><tr><td><a href="./guide/structure.html">2. 项目结构</a></td><td>看懂一个模组工程的每个文件，以及工具链替你做了什么</td></tr><tr><td><a href="./guide/mixin.html">3. 实验 Mixin</a></td><td>不改游戏源码地改写游戏类，含完整可复制的例子</td></tr><tr><td><a href="./guide/content.html">4. 植物与僵尸</a></td><td>用 <code>api-plant</code> / <code>api-zombie</code> 注册内容与覆盖已有数值</td></tr><tr><td><a href="./guide/resources.html">5. 资源与美术</a></td><td>图片、reanimation、散包覆盖 pak</td></tr><tr><td><a href="./guide/events.html">6. 事件与生命周期</a></td><td>用 <code>api-events</code> 观察游戏，以及什么时候不该用它</td></tr><tr><td><a href="./guide/content-mod.html">7. 实例精读</a></td><td><code>pvz-content-mod</code> 逐个文件读完：三株红植物是怎么长出来的</td></tr><tr><td><a href="./guide/build.html">8. 构建、测试与发布</a></td><td>把模组构建、测试、发布并交给玩家</td></tr><tr><td><a href="./guide/reference.html">9. API 速查</a></td><td>需要查类名与方法时翻这一页</td></tr></tbody></table><p>英文版在 <code>/en/</code>，与中文一一对应。</p><h2 id="工作区里真实存在的东西" tabindex="-1">工作区里真实存在的东西 <a class="header-anchor" href="#工作区里真实存在的东西" aria-label="Permalink to “工作区里真实存在的东西”">​</a></h2><p>文档里的每一段代码都来自工作区里的真实工程，可以照着读、照着跑：</p><table tabindex="0"><thead><tr><th>工程</th><th>是什么</th></tr></thead><tbody><tr><td><code>PvZ-Portable/</code></td><td>游戏本体（模组 id <code>pvz-portable</code>），<strong>不是</strong>模组</td></tr><tr><td><code>fabric-api/</code></td><td>模组 API：<code>api-base</code>、<code>api-events</code>、<code>api-plant</code>、<code>api-resource</code>、<code>api-zombie</code>，聚合坐标 <code>cn.enaium.fabricpvz:fabric-api</code></td></tr><tr><td><code>loom/</code></td><td>工具链 Gradle 插件 <code>cn.enaium.fabricpvz.loom</code>：一行插件给你游戏本体与版本包清单里的库（Loader、Mixin、ASM、日志栈、LWJGL）、<code>runClient</code> 与 jar-in-jar</td></tr><tr><td><code>pvz-example-mod/</code></td><td>最小可运行示例：事件 + 三个 mixin</td></tr><tr><td><code>pvz-content-mod/</code></td><td>教学实例：三株红植物，注册 + 艺术管线 + 端到端测试</td></tr><tr><td><code>pvz-mod-95-edition/</code></td><td>大型改版实例：以规则与数值覆盖为主的 Kotlin 模组</td></tr></tbody></table><p>表中的每个工程都能直接打开对照；文档里的构建脚本与代码片段以它们的当前内容为准。 工具链只提供游戏本身与版本包清单里的库，Kotlin、JUnit、<code>fabric-language-kotlin</code> 与 API 都由每个模组自己声明。</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};